1501:   private async prepareExecution<T>(
1502:     input: ToolExecutionInput,
1503:     next: (prepared: ScheduledToolPreparation) => T | PromiseLike<T>,
1504:   ): Promise<T> {
1505:     const created = this.createExecution(input)
1506:     if (created.kind !== 'ready') return next(created)
1507:     const exec = created.exec
1508:     if (this.callerCancelled(exec)) {
1509:       return next({ kind: 'final-result', exec, result: toolAbortedBeforeDispatchResult() })
1510:     }
1511:     try {
1512:       const carrier = scopeTarget(this, exec.agent)
1513:       const gate = await this.ctx.waterfall(
1514:         carrier, 'tools/pre-execute', exec,
1515:         () => Promise.resolve<PreToolDecision>({ kind: 'allow' }),
1516:       )
1517:       const askResolution = gate.kind === 'ask'
1518:         ? await this.serviceAsk(exec, gate)
1519:         : { decision: gate, approvalCancelled: false }
1520:       const { decision } = askResolution
1521:       if (this.callerCancelled(exec) && askResolution.approvalCancelled) {
1522:         return await next({ kind: 'post-result', exec, result: toolAbortedBeforeDispatchResult() })
1523:       }
1524:       if (decision.kind === 'cancel') {
1525:         return await next({ kind: 'post-result', exec, result: toolAbortedBeforeDispatchResult() })
1526:       }
1527:       const denialReason = decision.kind === 'allow' ? this.guardReason(exec) : decision.reason
1528:       const denialInfo = decision.kind === 'deny' ? decision.info : undefined
1529:       if (denialReason !== undefined) {
1530:         return await next({
1531:           kind: 'post-result',
1532:           exec,
1533:           result: this.materializeFinalResult({
1534:             content: [{ type: 'text', text: `Error: ${denialReason}` }],
1535:             isError: true,
1536:             error: { message: denialReason, ...denialInfo === undefined ? {} : { info: denialInfo } },
1537:           }),
